from datetime import datetime

def hydrate_time(nanoseconds, tz=None):
    if nanoseconds < 0:
        raise ValueError("Negative nanoseconds are not supported")
    if tz is None:
        tz = datetime.now().tzname
    days, seconds, microseconds = divmod(nanoseconds, 864000000000)
    hours, seconds = divmod(seconds, 36000000000)
    minutes, seconds = divmod(seconds, 600000000)
    return datetime(
        (days + 24 * hours + 1440 * minutes + 86400 * microseconds) // 10000000000,  # microseconds to seconds
        tzinfo=tz,
    )

