def values(self, *keys):
    """ Return the values of the record, optionally filtering to
       include only certain values by index or key.

       :param keys: indexes or keys of the items to include; if none
                    are provided, all values will be included
       :return: list of values
       :rtype: list
       """
    filtered_items = {}
    include_index = kwargs.get('include_index', [])
    include_key = kwargs.get('include_key', [])

    for key in self._items:
        if include_index and key.index in include_index:
            filtered_items[key.idx] = key.value
        elif include_key and key.key in include_key:
            filtered_items[key.idx] = key.value

    if keys:
        values = []
        for key in keys:
            if key in filtered_items:
                values.append(filtered_items[key])
            elif isinstance(key, int):
                value = self._items[key].value
                values.append(value)
    else:
        values = [item.value for item in filtered_items.values()]

    return values

def round_half_to_even(n):
    """
        Round half to even, meaning that if the fractional part is 0.5, it rounds to the nearest even integer.
        For example: round_half_to_even(1.5) = 2, round_half_to_even(2.5) = 2,
                     round_half_to_even(3.5) = 4, round_half_to_even(4.5) = 4.

        :param n:
        :return:
    """

    if n.is_integer():
        return int(n)

    fractional_part = n - int(n)
    if fractional_part == 0.5:
        if int(n) % 2 == 0:
            return n
        else:
            return n + 1
    else:
        return round(n)

