def cached(cache, key=hashkey, lock=None):
    """Decorator to wrap a function with a memoizing callable that saves
    results in a cache.

    """
    def decorator(func):
        if cache is None:
            def wrapper(*args, **kwargs):
                return func(*args, **kwargs)
        elif lock is None:
            def wrapper(*args, **kwargs):
                k = key(*args, **kwargs)
                try:
                    return cache[k]
                except KeyError:
                    pass  # key not found
                v = func(*args, **kwargs)
                try:
                    cache[k] = v
                except ValueError:
                    pass  # value too large
                return v
        else:
            def wrapper(*args, **kwargs):
                k = key(*args, **kwargs)
                try:
                    with lock:
                        return cache[k]
                except KeyError:
                    pass  # key not found
                v = func(*args, **kwargs)
                try:
                    with lock:
                        cache[k] = v
                except ValueError:
                    pass  # value too large
                return v
        return _update_wrapper(wrapper, func)
    return decorator

def ttl_cache(maxsize=128, ttl=600, timer=time.monotonic, typed=False):
    """Decorator to wrap a function with a memoizing callable that saves
    up to `maxsize` results based on a Least Recently Used (LRU)
    algorithm with a per-item time-to-live (TTL) value.

    """
    cache = ttl_cache.Cache(maxsize, ttl, timer, typed)
    def decorator(fn):
        if not inspect.isfunction(fn):
            raise ValueError('The @ttl_cache decorator must be applied innermost of all decorators.')

        @functools.wraps(fn)
        def memoize(*args, **kwargs):
            key = cache.key_for_fn_args(fn, *args, **kwargs)
            if key in cache:
                if cache.is_expired(key):
                    cache.delete(key)
                    return cache.fetch(key)
                return cache.fetch(key)
            result = fn(*args, **kwargs)
            cache.put(key, result)
            return result

        @contextmanager
        def put(*args, **kwargs):
            key = cache.key_for_fn_args(fn, *args, **kwargs)
            yield functools.partial(cache.set, key, result)
        memoize.put = put

        def forget(*args, **kwargs):
            key = cache.key_for_fn_args(fn, *args, **kwargs)
            if key in cache:
                cache.delete(key)
        memoize.forget = forget

        def clear():
            cache.clear()
        memoize.clear = clear

        return memoize

    return decorator

