def lfu_cache(maxsize=128, typed=False):
    def decorator(func):
        cache = OrderedDict()
        cache_size = 0

        def key_func(*args, **kwargs):
            if not typed:
                args = tuple(hash(arg) for arg in args)
                kwargs = tuple((key, hash(value)) for key, value in kwargs.items())
            return args + tuple(hash(tuple(value) for value in values) for values in kwargs.values())

        @functools.wraps(func)
        def memoize(*args, **kwargs):
            key = key_func(*args, **kwargs)
            if key in cache:
                cache.move_to_end(key, last=False)
                return cache[key]
            if cache_size >= maxsize:
                least_frequent_key, _ = heapq.heappop(list(cache.items()))
                del cache[least_frequent_key]
                cache_size -= 1
            cache[key] = func(*args, **kwargs)
            heapq.heappush(cache.items(), (cache_size, key))
            cache_size += 1
            return cache[key]

        return utils.lru_wrapper(output_func=memoize, function_name=func.__name__)
    return decorator

