def _legacy_mergeOrderings(orderings):
    merged_order = list(orderings[0])
    for o in orderings[1:]:
        for i, key in enumerate(o):
            if key not in merged_order:
                merged_order.insert(i, key)
            else:
                if merged_order[i:].index(key) < o[i:].index(key):
                    merged_order = merged_order[:i] + o[i:] + merged_order[i:]
