        """Validate a given inventory.

        If extract_spec_version is True then will look at the type value to determine
        the specification version. In the case that there is no type value or it isn't
        valid, then other tests will be based on the version given in self.spec_version.
        """
        if not isinstance(inventory, dict):
            raise ValueError("Inventory must be a dictionary.")

        if extract_spec_version and 'type' not in inventory:
            # If extract_spec_version is True, check if the type value is present and valid
            if 'version' in inventory:
                version = inventory['version']
                if version == self.spec_version:
                    # If the version matches, return the inventory
                    return inventory
                else:
                    # If the version does not match, raise an error
                    raise ArgumentError("Inventory version does not match self.spec_version.")
            else:
                # If there is no version in the inventory, raise an error
                raise ArgumentError("Inventory does not have a version attribute.")
        else:
            # If extract_spec_version is False, use the type value to validate the inventory
            if 'type' not in inventory:
                # If there is no type value, raise an error
                raise ArgumentError("Inventory does not have a type attribute.")

            # Validate the type value
            if not isinstance(inventory['type'], self.list_item_type):
                # If the type value is not of the expected type, raise an error
                raise ArgumentError("Type value is not of the expected type.")

        # Return the inventory if all tests pass
        return inventory

