def absorb(self, args):
    """
    Given an `args` sequence of expressions, return a new list of expression
    applying absorption and negative absorption.

    See https://en.wikipedia.org/wiki/Absorption_law

    Absorption::

        A & (A | B) = A, A | (A & B) = A

    Negative absorption::

        A & (~A | B) = A & B, A | (~A & B) = A | B

    Args:
        args (list): Sequence of expressions.

    Returns:
        list: New list of expressions after applying absorption and negative absorption.
    """
    absorbed = []  # To store the result list
    for expr in args:
        # Check for absorption
        if expr.startswith('&') and expr != '&':
            # Split the expression into parts
            parts = expr.split(' & ')
            if len(parts) == 2:
                # Check if both sides involve absorption
                if parts[0].startswith('A') and parts[1].startswith('A'):
                    absorbed.append(parts[0])
                elif parts[0].startswith('A') and parts[1].startswith('~A'):
                    absorbed.append(parts[1])
                elif parts[0].startswith('~A') and parts[1].startswith('A'):
                    absorbed.append(parts[1])
                elif parts[0].startswith('~A') and parts[1].startswith('~A'):
                    absorbed.append(parts[0])
            # Check if only one side involves absorption
            elif len(parts) == 1:
                if parts[0].startswith('A'):
                    absorbed.append(parts[0])
        # Check for negative absorption
        elif expr.startswith('|') and expr != '|':
            # Split the expression into parts
            parts = expr.split(' | ')
            if len(parts) == 2:
                # Check if both sides involve negative absorption
                if parts[0].startswith('A') and parts[1].startswith('A'):
                    absorbed.append(parts[0])
                elif parts[0].startswith('A') and parts[1].startswith('~A'):
                    absorbed.append(parts[0])
                elif parts[0].startswith('~A') and parts[1].startswith('A'):
                    absorbed.append(parts[1])
                elif parts[0].startswith('~A') and parts[1].startswith('~A'):
                    absorbed.append(parts[0])
            # Check if only one side involves negative absorption
            elif len(parts) == 1:
                if parts[0].startswith('A'):
                    absorbed.append(parts[0])

    return absorbed

