def run_command(commands, args, cwd=None, verbose=False, hide_stderr=False, env=None):
    """Call the given command(s)."""

    if not isinstance(commands, (list, tuple)):
        raise TypeError("The 'commands' parameter must be a list or tuple of commands.")
    if not isinstance(args, (list, tuple)):
        raise TypeError("The 'args' parameter must be a list or tuple of arguments.")

    complete_command = [commands]
    for arg in args:
        if arg is None:
            complete_command.append(arg)
        else:
            complete_command.append(f"'{arg}'")

    command = complete_command

    output = None
    try:
        output = subprocess.check_output(command, cwd=cwd, shell=False, stderr=subprocess.STDOUT if not hide_stderr else subprocess.PIPE)
    except subprocess.CalledProcessError as e:
        if hide_stderr:
            output = getattr(e, 'stderr').decode('utf-8') if e.stderr is not None else None
        else:
            output = e.stderr.decode('utf-8') if e.stderr is not None else str(e)
        print(output)
        return None

    return output

