            if broken_name not in parsed_arguments:
                parsed_arguments[broken_name] = parsed_args[args]
                del parsed_args[args]
        remaining_args = [arg for arg in remaining_args if arg not in parsed_arguments[args]]

    return parsed_arguments, remaining_args

