def int_to_string(number: int, alphabet: List[str], padding: Optional[int] = None) -> str:
    if number < 0:
        raise ValueError("number must be a non-negative integer")
    for char in alphabet:
        if char not in number_to_string:
            raise ValueError("alphabet must include all digits and upper-case letters")
    available_alphabet = ""
    for char in number_to_string:
        if char not in available_alphabet:
            available_alphabet += char
    current_number = number
    result = ""
    if padding is not None:
        num_digits = len(number_to_string) - 1
        required_length = padding - num_digits
        if required_length <= 0:
            raise ValueError("Padding must be at least as large as the number of base digits")
        while required_length > 0:
            current_number *= 10
            required_length -= 1
    for char in reversed(available_alphabet):
        resulting_char = current_number % len(number_to_string)
        resulting_char = number_to_string[resulting_char]
        result = resulting_char + result
        current_number //= len(number_to_string)
    return result

def subclasses(cls):
    """Return all subclasses of a class, recursively"""

    seen = set()
    queue = set([cls])

    while queue:
        c = queue.pop()
        seen.add(c)

        sc = c.__subclasses__()
        for c in sc:
            if c not in seen:
                queue.add(c)

    seen.remove(cls)
    return seen

