def split(s, platform='this'):
    """Multi-platform variant of shlex.split() for command-line splitting.
    For use with subprocess, for argv injection etc. Using fast REGEX.

    platform: 'this' = auto from current platform;
              1 = POSIX;
              0 = Windows/CMD
              (other values reserved)
    """
    # Determine platform-specific shlex rules
    shlex_rules = {
        'this': shlexposixrules if platform == '1' else shlexcmdsyntaxrules,
        '1': shlexposixrules,
        '0': shlexcmdsyntaxrules
    }
    shlex_rules = shlex_rules.get(platform, shlexposixrules)

    # Split the string using platform-specific rules
    return shlex.split(s, **shlex_rules)

