import datetime

def parse_frequency(frequency):
    """Given a frequency string with a number and a unit of time, return a corresponding
    datetime.timedelta instance or None if the frequency is None or "always".

    For instance, given "3 weeks", return datetime.timedelta(weeks=3)

    Raise ValueError if the given frequency cannot be parsed.
    """
    if frequency is None or frequency.strip().lower() == "always":
        return None

    match = re.match(r'^(\d+)\s*([a-zA-Z]+)$', frequency)
    if not match:
        raise ValueError("Invalid frequency format")

    unit = match.group(2).lower()
    num = int(match.group(1))

    if unit == "hours":
        return datetime.timedelta(hours=num)
    elif unit == "days":
        return datetime.timedelta(days=num)
    elif unit == "weeks":
        return datetime.timedelta(weeks=num)
    elif unit == "months":
        return datetime.timedelta(days=num * 30)
    elif unit == "years":
        return datetime.timedelta(days=num * 365)
    else:
        raise ValueError("Unknown unit: {}".format(unit))

def is_local(host):
    """
    Checks if the host is the localhost

    :param host: The hostname or ip
    :return: True if the host is the localhost
    """
    for addrinfo in socket.getaddrinfo(host, 0, 0, 0, socket.IPPROTO_TCP):
        family, socktype, proto, _, sockaddr = addrinfo
        if family == socket.AF_INET and sockaddr[0] == '127.0.0.1':
            return True
        elif family == socket.AF_INET6 and sockaddr[0] == '::1':
            return True
    return False

