class ExpandRecursiveGlobs:
    _RECURSIVE_GLOB_LIMIT = 10

    def AppendPathEntries(
        self, path: str, path_separator: str, iterations: int, skip_first: bool
    ) -> List[str]:
        glob_regex = r'(.*)?{0:s}\*\*(\d{{1,2}})?({0:s})?$'.format(
            re.escape(path_separator))

        match = re.search(glob_regex, path)
        if not match:
            return [path]

        skip_first = False
        if match.group(3):
            skip_first = True
        if match.group(2):
            iterations = int(match.group(2))
        else:
            iterations = self._RECURSIVE_GLOB_LIMIT
            logger.warning((
                'Path "{0:s}" contains fully recursive glob, limiting to 10 '
                'levels').format(path))

        return self._expand_recursive_paths(
            match.group(1), path_separator, iterations, skip_first)

    def _expand_recursive_paths(
        self, path: str, path_separator: str, iterations: int, skip_first: bool
    ) -> List[str]:
        if not path.endswith('**'):
            return [path]
        parts = path.split('**')
        if len(parts) == 1:
            return [path]

        expanded_parts = []
        for i in range(iterations):
            base_part = parts.pop()
            for part in base_part:
                expanded_part = ""
                has_globs = False
                for segment in part.split(path_separator):
                    if has_globs:
                        expanded_part += path_separator
                    has_globs |= re.search(r'\*\*', segment)
                expanded_parts.append(expanded_part)
            if skip_first:
                expanded_parts = expanded_parts[1:]

        result = [parts[0]]
        for part in expanded_parts:
            result.extend(parts + [part])
        return result

    def make_find_paths(find_paths):
        '''
        Given a sequence of path fragments or patterns as passed to `--find`, transform all path
        fragments into glob patterns. Pass through existing patterns untouched.

        For example, given find_paths of:

          ['foo.txt', 'pp:root/somedir']

        ... transform that into:

          ['sh:**/*foo.txt*/**', 'pp:root/somedir']
        '''
        pattern_parts = []
        pattern_active = False
        for path in find_paths:
            if path == '**':
                pattern_active = True
                pattern_parts.append(None)
            elif path == '*':
                if pattern_active:
                    regex_part = path.replace('**', '{}{}**', '{}')
                    pattern_parts[-1] = regex_part.format(
                        r'"', path_separator, r'"')
                else:
                    pattern_parts.append(r'.*')
            elif path:
                pattern_parts.append(path)
        pattern_parts = [p for p in pattern_parts if p]
        result = []
        for part in pattern_parts:
            if part is None:
                result.append("sh:**/*")
            elif part.startswith('"') and part.endswith('"'):
                part = part[1:-1]
            result.append(f'pp:{part}')
        return result

def _parse_image_ref(image_href: str) -> Tuple[str, str, bool]:
    """Parse an image href into composite parts.

    :param image_href: href of an image
    :returns: a tuple of the form (image_id, netloc, use_ssl)
    :raises ValueError:

    """
    if not image_href.startswith('https://'):
        raise ValueError("Image href is not a valid HTTPS URL")

    parsed_url = urllib.parse.urlparse(image_href)
    if hasattr(parsed_url, 'netloc'):
        netloc = parsed_url.netloc
    else:
        netloc = parsed_url.hostname

    if 'https' in parsed_url.scheme:
        use_ssl = True
    else:
        use_ssl = False

    parts = image_href.split('.')
    if len(parts) < 2:
        raise ValueError("Image[href] has no suffix")

    image_id = parts[:-1]
    image_id = ".".join(image_id)
    if not image_id:
        raise ValueError("Image[href] has no valid identifier")

    return image_id, netloc, use_ssl

