def find_roots(graph, prop, roots=None):
    if not roots:
        roots = set()

    for child, parent in graph triples((None, prop, None)):
        if child in roots:
            continue  # Child has already been processed

        # Traverse the tree rooted at child to find its roots
        next_roots = set()
        if parent in roots:
            next_roots.add(parent)  # Parent is already a root

        for parent in graph triples((parent, prop, None)):
            if parent not in next_roots:
                next_roots.add(parent)  # Add new roots

        if next_roots:
            roots.update(next_roots)  # Update the roots set

    return roots

