            if os.path.isdir(os.path.join(buildroot, putative_dir)):
                build_files = list(BuildFile.get_build_files_family(
                    FileSystemProjectTree(buildroot),
                    putative_dir))
                if build_files:
                    path = build_files[0].relpath
                else:
                    return None

        if os.path.exists(os.path.join(buildroot, path)):
            # The reporting server serves file content at /browse/<path_from_buildroot>.
            return '/browse/{}'.format(path)
        else:
            return None

    def maybe_add_link(url, text):
        return '<a target="_blank" href="{}">{}</a>'.format(url, text) if url else text

    return _PATH_RE.sub(lambda m: maybe_add_link(memoized_to_url(m), m.group(0)), text)

def fetch_content_type(url: str) -> Optional[str]:
    import requests
    try:
        response = requests.head(url, headers={'Host': url.split('//')[1].split('/')[0]})
        if response.status_code == 200:
            return response.headers['content-type']
    except requests.RequestException as e:
        print(f"Error fetching content type for URL {url}: {str(e)}")
    return None

def xml_children_as_dict(node):
    """
    Turn the children of an Element into a dict, keyed by tag name.

    This is only a shallow conversation - child nodes are not recursively processed.
    """
    children_dict = {}
    for child in node:
        children_dict[child.tag] = child.text if child.text else ""
        if hasattr(child, 'children'):
            children_dict[child.tag] = xml_children_as_dict(child)
    return children_dict

