def try_retrieve_webfinger_document(handle: str) -> Optional[str]:
    """
    Try to retrieve an RFC7033 webfinger document. Does not raise if it fails.

    :arg handle: Remote handle to retrieve
    :returns: Optional[str]
    """
    if not handle:
        raise ValueError("Remote handle cannot be empty")
    try:
        _, _, exception = fetch_document(host=handle, path="/.well-known/webfinger?resource=acct:%s" % quote(handle))
        if exception:
            return None
    except Exception as e:
        # Handle any exceptions that may occur during the fetch
        print(f"Failed to retrieve webfinger document for handle {handle}: {e}")
        return None
    return parse_diaspora_webfinger(fetch_document(host=handle, path="/.well-known/webfinger?resource=acct:%s" % quote(handle))[0])

