def list_of_file_names(settings_dirs, spec_option):
    """ Create a new IniType complex type based on the settings directories and spec option

    Args:
        settings_dirs (list): List of directories where the settings files are stored
        spec_option (str): The spec option to filter the settings files

    Returns:
        list: List of fully qualified filenames that match the specified spec option
    """

    matching_files = []
    for directory in settings_dirs:
        try:
            files = os.listdir(directory)
            for file in files:
                if file.endswith('.ini'):
                    if spec_option in file:
                        matching_files.append(os.path.join(directory, file))
        except PermissionError:
            continue
        except OSError:
            continue

    return matching_files

