def validate_from_content(cls, spec_content=None):
    if spec_content is None:
        raise IRValidatorException("spec_content argument must be supplied")
    try:
        spec = yaml.safe_load(spec_content)
    except yaml.YAMLError as e:
        raise IRValidatorException("Error parsing spec content: {}".format(e))
    required_fields = cls.get_required_fields()
    missing_fields = [field for field in required_fields if field not in spec]
    if missing_fields:
        raise IRValidatorException("Missing required fields in spec: {}".format(missing_fields))
    return spec

