def validate_arg_deprecation(self, cli_args, answer_file_args):
    """
    Validates and prints the deprecated arguments.

    :param cli_args: the dict of arguments from cli
    :param answer_file_args:  the dict of arguments from files
    """
    for deprecated_arg, new_arg in self.parsed_yaml.get('deprecated_args', {}).items():
        if deprecated_arg in cli_args:
            warnings.warn(
                f"Keyword argument '{deprecated_arg}' in CLI parameters was deprecated in favour of '{new_arg}'. '{deprecated_arg}' will be removed in a future version.",
                category=DeprecationWarning,
                stacklevel=2,
            )
            cli_args.pop(deprecated_arg)
            if new_arg in answer_file_args:
                warnings.warn(
                    f"Keyword argument '{new_arg}' in file-based parameters wasdeprecated in favour of '{deprecated_arg}' in CLI parameters. '{new_arg}' will be removed in a future version.",
                    category=DeprecationWarning,
                    stacklevel=2,
                )
                answer_file_args.pop(new_arg)
        else:
            if answer_file_args and new_arg in answer_file_args:
                warnings.warn(
                    f"Invalid argument found in file-based parameters: '{deprecated_arg}'. Please ensure it is not used.",
                    category=DeprecationWarning,
                    stacklevel=2,
                )
            else:
                warnings.warn(
                    f"Invalid argument found in param {new_arg}. Please ensure it is not used.",
                    category=DeprecationWarning,
                    stacklevel=2,
                )

